inline std::optional<float> Cell(int column, int row)
{
    if (column < 0 || row < 0 || column >= Columns || row >= Rows)
        return std::nullopt;
    uint16_t const value = HeightCenti[std::size_t(row) * Columns + std::size_t(column)];
    if (!value)
        return std::nullopt;
    return 70.0f + float(value) / 100.0f;
}

// Bilinear height at (x, y); corners without navmesh drop out and the rest
// are reweighted. Outside the grid, or with no corner, nothing.
inline std::optional<float> Height(float x, float y)
{
    float const gx = (x - OriginX) / Step;
    float const gy = (y - OriginY) / Step;
    int const column = int(std::floor(gx));
    int const row = int(std::floor(gy));
    if (column < 0 || row < 0 || column >= Columns - 1 || row >= Rows - 1)
        return std::nullopt;
    float const fx = gx - float(column);
    float const fy = gy - float(row);
    float const weights[4] = { (1 - fx) * (1 - fy), fx * (1 - fy), (1 - fx) * fy, fx * fy };
    std::optional<float> const corners[4] = { Cell(column, row), Cell(column + 1, row),
        Cell(column, row + 1), Cell(column + 1, row + 1) };
    float sum = 0.0f;
    float weight = 0.0f;
    for (int corner = 0; corner < 4; ++corner)
        if (corners[corner])
        {
            sum += *corners[corner] * weights[corner];
            weight += weights[corner];
        }
    if (weight <= 0.0f)
        return std::nullopt;
    return sum / weight;
}

// True when all four grid cells around (x, y) have navmesh: not in or beside
// a pillar hole (e.g. the NE pillar near (176, -192) and the SE one near
// (177, -257)), and inside the table.
inline bool Solid(float x, float y)
{
    float const gx = (x - OriginX) / Step;
    float const gy = (y - OriginY) / Step;
    int const column = int(std::floor(gx));
    int const row = int(std::floor(gy));
    return Cell(column, row) && Cell(column + 1, row) && Cell(column, row + 1)
        && Cell(column + 1, row + 1);
}

// A destination on the hall floor: its x/y with the floor height, or `point`
// unchanged outside the table.
inline Vector3 OnFloor(Vector3 point)
{
    if (std::optional<float> const z = Height(point.X, point.Y))
        point.Z = *z;
    return point;
}
